from txn import Coordinator, Crash, DecisionLog, SagaRunner, Shard, Step, StaleTerm


def build():
    # Account X on shard1 holds 1,000.00 and account Y on shard2 holds nothing (integer cents).
    return {
        "shard1": Shard("shard1", balances={"X": 100000}),
        "shard2": Shard("shard2", balances={"Y": 0}),
    }


def total(shards):
    return sum(sum(s.balances.values()) for s in shards.values())


LEGS_9041 = [("shard1", "X", -25000), ("shard2", "Y", 25000)]


def test_commit_moves_money_once():
    shards = build()
    log = DecisionLog()
    coord = Coordinator(12, log, shards)
    assert coord.transfer("9041", LEGS_9041) == "committed"
    assert shards["shard1"].balances["X"] == 75000
    assert shards["shard2"].balances["Y"] == 25000
    assert log.decision("9041") == "commit"


def test_duplicate_transfer_returns_stored_decision():
    shards = build()
    coord = Coordinator(12, DecisionLog(), shards)
    coord.transfer("9041", LEGS_9041)
    assert coord.transfer("9041", LEGS_9041) == "committed"
    assert shards["shard1"].balances["X"] == 75000


def test_crash_after_prepare_is_presumed_aborted():
    shards = build()
    log = DecisionLog()
    try:
        Coordinator(12, log, shards).transfer("9042", LEGS_9041, crash_at="prepared")
    except Crash:
        pass
    assert shards["shard1"].locks == {"X": "9042"}  # in doubt, locked
    Coordinator(13, log, shards).resume()
    assert log.decision("9042") == "abort"
    assert shards["shard1"].locks == {} and shards["shard2"].locks == {}
    assert shards["shard1"].balances["X"] == 100000
    assert total(shards) == 100000


def test_stale_coordinator_decision_is_refused():
    shards = build()
    log = DecisionLog()
    try:
        Coordinator(12, log, shards).transfer("9042", LEGS_9041, crash_at="prepared")
    except Crash:
        pass
    Coordinator(13, log, shards).resume()
    # The old coordinator wakes up and tries to commit under term 12.
    try:
        shards["shard1"].commit(12, "9042")
        raise AssertionError("stale commit was accepted")
    except StaleTerm:
        pass


def test_locked_account_refuses_second_transfer():
    shards = build()
    log = DecisionLog()
    try:
        Coordinator(12, log, shards).transfer("9042", LEGS_9041, crash_at="prepared")
    except Crash:
        pass
    coord = Coordinator(13, log, shards)
    assert coord.transfer("9050", [("shard1", "X", -100), ("shard2", "Y", 100)]) == "committed"
    # The first transfer was in doubt and resumed with an abort, so X is free again.
    assert shards["shard1"].balances["X"] == 100000 - 100


def test_unreachable_participant_aborts_and_redelivers_later():
    shards = build()
    log = DecisionLog()
    coord = Coordinator(12, log, shards)
    shards["shard2"].available = False
    assert coord.transfer("9044", LEGS_9041) == "aborted"
    assert shards["shard1"].locks == {}  # the abort reached the reachable side
    shards["shard2"].available = True
    coord.resume()
    assert shards["shard2"].outcome["9044"] == "abort"
    assert total(shards) == 100000


def test_saga_compensates_refused_credit():
    shards = build()
    shards["shard2"].closed.add("Y")
    store = {}
    runner = SagaRunner(shards, store)
    runner.start("9043", [
        Step("debit principal", "shard1", "X", -25000),
        Step("charge fee", "shard1", "X", -250),
        Step("credit destination", "shard2", "Y", 25000),
    ])
    assert runner.run("9043") == "compensated"
    assert shards["shard1"].balances["X"] == 100000  # principal and fee both returned
    assert total(shards) == 100000


def test_saga_compensation_waits_out_partition():
    shards = build()
    shards["shard2"].closed.add("Y")
    original = shards["shard2"].apply

    def refuse_and_partition(key, account, delta):
        shards["shard1"].available = False  # the partition begins as the credit is refused
        return original(key, account, delta)

    shards["shard2"].apply = refuse_and_partition
    store = {}
    runner = SagaRunner(shards, store)
    runner.start("9043", [
        Step("debit principal", "shard1", "X", -25000),
        Step("charge fee", "shard1", "X", -250),
        Step("credit destination", "shard2", "Y", 25000),
    ])
    assert runner.run("9043") == "compensating"
    assert store["9043"]["state"] == "compensating"
    assert shards["shard1"].balances["X"] == 74750  # visibly reduced while compensation waits

    shards["shard1"].available = True
    assert runner.run("9043") == "compensated"
    assert shards["shard1"].balances["X"] == 100000
    assert total(shards) == 100000


def test_saga_step_applies_once_per_key():
    shards = build()
    assert shards["shard1"].apply("9043:0:fwd", "X", -10000) == "ok"
    assert shards["shard1"].apply("9043:0:fwd", "X", -10000) == "ok"
    assert shards["shard1"].balances["X"] == 90000
```

## Explanation

**The decision log is the commit point.** `Coordinator._decide` appends the decision to `DecisionLog` before it calls any participant. Recovery depends only on the log, so the log's durability is the guarantee. In production it is a consensus-backed log, as the sharding section described. Here it is a list that outlives the coordinator object, which is enough to show the recovery logic.

**Participants fence by coordinator term.** `Shard._fence` rejects any 2PC message whose term is older than the highest term the shard has accepted. The test `test_stale_coordinator_decision_is_refused` replays the worked example: the old coordinator in term 12 tries to commit after term 13 has aborted the transfer, and the shard refuses. This is the same fencing rule as the leader election section, applied to decisions instead of writes.

**Locks and the in-doubt window.** A participant that prepares records the transfer and holds the account lock until it hears a decision. `test_crash_after_prepare_is_presumed_aborted` shows the lock held during the crash, and `test_locked_account_refuses_second_transfer` shows a second transfer refused while the account is in doubt. The saga path also respects the lock: `Shard.apply` returns `Unavailable` for a locked account, so a saga waits instead of slipping past an in-doubt transfer.

**Presumed abort on recovery.** `Coordinator.resume` aborts every transfer with a begin record and no decision. This is safe only because the coordinator writes its commit record before any commit is sent, so an undecided transfer cannot have been committed anywhere. The test checks that the abort releases both locks and leaves the balances unchanged.

**Undelivered decisions.** `_deliver` returns the shards it could not reach, and `resume` delivers again. `test_unreachable_participant_aborts_and_redelivers_later` covers the case where one participant is cut off during the abort. The reachable shard releases its lock at once, and the unreachable one learns the decision when the coordinator resumes.

**Sagas persist their state.** `SagaRunner` writes the step pointer and the compensation pointer into `store` after every change, so a restarted runner resumes from the right place. Each forward and compensating call carries a key, `saga_id:step:fwd` or `saga_id:step:comp`, and `Shard.apply` returns the stored result for a repeated key. `test_saga_step_applies_once_per_key` shows the key check; the saga tests show the rest.

**Compensations wait out partitions.** `_call` retries an unavailable shard a bounded number of times, and then `run` returns `compensating` without losing progress. `test_saga_compensation_waits_out_partition` reproduces the worked example's Part 3: the fee reversal and the principal credit wait while region A is cut off, the visible balance stays reduced, and the saga reaches `compensated` once the partition heals. Money is conserved only at the end, which is the intermediate-state trade-off from the trade-offs section.

**The pivot.** `start` takes a pivot index, and `run` refuses to compensate a refusal at or after it. The default is no pivot, so every step is compensatable. In a production saga, the pivot is the step that must not be refused, such as the fee record in the worked example. Making the pivot explicit turns a design decision into a check.

**What the sketch does not model.** It runs one transfer at a time, so it does not show isolation between concurrent transfers beyond the account lock. It has no real timeouts or backoff, so `MAX_ATTEMPTS` stands in for a retry budget. It has no persistence, so the "durable" log and saga store are only durable in the sense that the test keeps references to them. It does not check that a saga's steps and the 2PC locks cover the same accounts consistently across shards. Each of these is a place where a production system needs more code and more tests.

**How to run it.** Place `txn.py` and `test_txn.py` in one directory and run `pytest -q`. The expected result is nine tests passing, with no assertion errors. If the stale-coordinator test fails, check `Shard._fence` first, since a missing term check is the usual cause. If the presumed-abort test fails, check that `DecisionLog.undecided` sees the begin record.

The next section covers the most common mistakes teams make with distributed transactions and how to catch each one, using these tests as the reference.

Key takeaway: The sketch shows that a Kestrel transfer across two shards is correct when the coordinator's decision log is the commit point, participants refuse decisions from older coordinator terms, in-doubt accounts stay locked until a decision arrives, and sagas persist their state and key every step so that compensations wait out a partition and each step applies once, and the tests replay transfer 9041's failure paths so that conservation and exactly-once behavior are checked rather than assumed, though the code has not yet been compiled or run.

# Code Example: Tracing and Observability Primitives for Kestrel

This section implements the primitives behind the earlier discussion: a W3C-style trace context, spans that record causal parents, a bounded exporter that never blocks the request path, a tail sampler that keeps failures and slow traces, routing by trace identifier, metric labels restricted to a fixed set, salted references in place of account identifiers, and an outbox that carries trace context to the relay. It also computes the protocol indicator for in-doubt age.

The code is a teaching model. One process stands in for several nodes, time comes from an injected fake clock, and exporters are in memory. It has not been compiled or run in this session. The expected results are described in the explanation and should be confirmed with `pytest` before anyone relies on them.

## `obs.py`

```python
"""Tracing and observability sketches for Kestrel.

Teaching model: one process stands in for several nodes, time comes from an
injected clock, and exporters are in memory. Nothing here has been compiled or run.
"""
import hashlib
import hmac
import itertools
from collections import deque
from dataclasses import dataclass, field

_ids = itertools.count(1)


def new_trace_id():
    return f"{next(_ids):032x}"


def new_span_id():
    return f"{next(_ids):016x}"


@dataclass(frozen=True)
class Context:
    """What crosses a hop: enough to create a child span elsewhere."""

    trace_id: str
    span_id: str
    sampled: bool = True

    def traceparent(self):
        return f"00-{self.trace_id}-{self.span_id}-{'01' if self.sampled else '00'}"


def parse_traceparent(header):
    version, trace_id, span_id, flags = header.split("-")
    if version != "00" or len(trace_id) != 32 or len(span_id) != 16:
        raise ValueError(f"malformed traceparent: {header}")
    return Context(trace_id, span_id, sampled=flags == "01")


@dataclass
class Span:
    trace_id: str
    span_id: str
    parent_id: str | None
    name: str
    node: str
    start_ms: float
    end_ms: float | None = None
    attrs: dict = field(default_factory=dict)
    events: list = field(default_factory=list)


class Exporter:
    """Bounded buffer. A full buffer drops the oldest span and counts the drop."""

    def __init__(self, capacity=10_000):
        self.buffer = deque(maxlen=capacity)
        self.dropped = 0

    def export(self, span):
        if len(self.buffer) == self.buffer.maxlen:
            self.dropped += 1
        self.buffer.append(span)


class Tracer:
    def __init__(self, node, exporter, clock):
        self.node = node
        self.exporter = exporter
        self.clock = clock

    def start(self, name, parent=None, **attrs):
        if parent is None:
            trace_id, parent_id = new_trace_id(), None
        else:
            trace_id, parent_id = parent.trace_id, parent.span_id
        span = Span(trace_id, new_span_id(), parent_id, name, self.node,
                    self.clock(), attrs=dict(attrs))
        return SpanScope(self, span)


class SpanScope:
    def __init__(self, tracer, span):
        self.tracer = tracer
        self.span = span

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        self.span.end_ms = self.tracer.clock()
        if exc is not None:
            self.span.attrs.setdefault("outcome", "error")
            self.span.attrs["error"] = type(exc).__name__
        self.tracer.exporter.export(self.span)
        return False  # observability never swallows the exception

    def context(self):
        return Context(self.span.trace_id, self.span.span_id)

    def set(self, **attrs):
        self.span.attrs.update(attrs)

    def event(self, name):
        self.span.events.append((self.tracer.clock(), name))


KEEP_OUTCOMES = {"aborted", "compensated", "refused", "retry", "error"}


class TailSampler:
    """Decides once per complete trace. The baseline draw depends only on the trace id,
    so any collector reaches the same decision without shared state."""

    def __init__(self, latency_budget_ms, baseline_rate):
        self.latency_budget_ms = latency_budget_ms
        self.baseline_rate = baseline_rate

    def keep(self, spans):
        if any(s.attrs.get("outcome") in KEEP_OUTCOMES for s in spans):
            return True
        duration = max(s.end_ms for s in spans) - min(s.start_ms for s in spans)
        if duration > self.latency_budget_ms:
            return True
        draw = int(spans[0].trace_id[-8:], 16) / 0xFFFFFFFF
        return draw < self.baseline_rate


def route(trace_id, collectors):
    # One trace always lands on one collector, so that collector sees every span.
    return collectors[int(trace_id[-8:], 16) % len(collectors)]


ALLOWED_LABELS = {"region", "shard", "outcome", "step"}


class Histogram:
    def __init__(self, name, max_series=5000):
        self.name = name
        self.max_series = max_series
        self.series = {}
        self.refused = 0

    def observe(self, value_ms, **labels):
        # A disallowed label is a developer error, caught by tests rather than in production.
        extra = set(labels) - ALLOWED_LABELS
        if extra:
            raise ValueError(f"{self.name}: label not allowed: {sorted(extra)}")
        key = tuple(sorted(labels.items()))
        if key not in self.series and len(self.series) >= self.max_series:
            self.refused += 1  # drop and count; never block the request path
            return
        self.series.setdefault(key, []).append(value_ms)


def hashed_ref(salt, account):
    """Opaque reference for trace attributes. Only the ledger maps it back to an account."""
    return hmac.new(salt, account.encode(), hashlib.sha256).hexdigest()[:16]


def write_outbox(outbox, txid, payload, ctx):
    # The row carries the trace context, so the relay can continue the trace later.
    outbox.append((txid, payload, ctx.traceparent()))


def relay(outbox, tracer, deliver):
    for txid, payload, header in outbox:
        parent = parse_traceparent(header)
        with tracer.start("outbox.relay", parent=parent, transfer=txid):
            deliver(txid, payload)


def p99(values):
    if not values:
        return 0.0
    ordered = sorted(values)
    return ordered[min(len(ordered) - 1, int(0.99 * len(ordered)))]
```

## `test_obs.py`

```python
import pytest

from obs import (
    Context, Exporter, Histogram, Span, TailSampler, Tracer,
    hashed_ref, p99, parse_traceparent, relay, route, write_outbox,
)


class FakeClock:
    def __init__(self):
        self.now = 0.0

    def __call__(self):
        return self.now

    def tick(self, ms):
        self.now += ms


def make_span(start, end, outcome=None):
    attrs = {"outcome": outcome} if outcome else {}
    return Span("a" * 32, "b" * 16, None, "transfer", "gateway", start, end, attrs)


def test_traceparent_round_trips():
    ctx = Context("a" * 32, "b" * 16)
    assert parse_traceparent(ctx.traceparent()) == ctx


def test_child_span_shares_trace_and_names_its_parent():
    clock, exporter = FakeClock(), Exporter()
    tracer = Tracer("gateway", exporter, clock)
    with tracer.start("transfer 9041") as root:
        with tracer.start("shard1.prepare", parent=root.context()):
            clock.tick(34)
    spans = {s.name: s for s in exporter.buffer}
    assert spans["shard1.prepare"].trace_id == spans["transfer 9041"].trace_id
    assert spans["shard1.prepare"].parent_id == spans["transfer 9041"].span_id


def test_outbox_relay_stays_in_the_transfer_trace():
    clock, exporter = FakeClock(), Exporter()
    shard1 = Tracer("shard1", exporter, clock)
    relay_node = Tracer("relay", exporter, clock)
    outbox = []
    with shard1.start("debit X", transfer="9041") as debit:
        write_outbox(outbox, "9041", ("Y", 25000), debit.context())
    clock.tick(300)  # the relay runs later, as it would in production
    relay(outbox, relay_node, deliver=lambda txid, payload: None)
    spans = {s.name: s for s in exporter.buffer}
    assert spans["outbox.relay"].trace_id == spans["debit X"].trace_id
    assert spans["outbox.relay"].parent_id == spans["debit X"].span_id
    assert spans["outbox.relay"].start_ms - spans["debit X"].end_ms == 300


def test_exception_is_recorded_and_not_swallowed():
    clock, exporter = FakeClock(), Exporter()
    tracer = Tracer("shard2", exporter, clock)
    with pytest.raises(RuntimeError):
        with tracer.start("shard2.prepare Y"):
            raise RuntimeError("leader stalled")
    assert exporter.buffer[0].attrs["outcome"] == "error"


def test_exporter_counts_dropped_spans():
    exporter = Exporter(capacity=2)
    for _ in range(3):
        exporter.export(make_span(0, 1))
    assert len(exporter.buffer) == 2
    assert exporter.dropped == 1


def test_tail_sampler_keeps_failures_and_slow_traces():
    sampler = TailSampler(latency_budget_ms=500, baseline_rate=0.0)
    assert sampler.keep([make_span(0, 10, "aborted")])
    assert sampler.keep([make_span(0, 900)])
    assert not sampler.keep([make_span(0, 10, "committed")])


def test_routing_is_stable_for_a_trace():
    collectors = ["c0", "c1", "c2"]
    trace_id = "c" * 32
    assert route(trace_id, collectors) == route(trace_id, collectors)


def test_histogram_rejects_account_label():
    histogram = Histogram("commit_latency_ms")
    with pytest.raises(ValueError):
        histogram.observe(180.0, region="A", account="X")


def test_hashed_reference_hides_the_account():
    ref = hashed_ref(b"salt", "X")
    assert ref != "X" and len(ref) == 16
    assert ref == hashed_ref(b"salt", "X")


def test_p99_reads_the_tail():
    values = [1.0] * 99 + [5000.0]
    assert p99(values) == 5000.0
```

## Explanation

**Context and the header.** `Context.traceparent` produces the W3C form, `00-<trace id>-<span id>-<flags>`, and `parse_traceparent` reads it back. The trace identifier is shared by the whole tree, and the span identifier names the caller. Everything that crosses a hop, whether an RPC or an outbox row, must carry this header. `test_traceparent_round_trips` checks that the format is lossless.

**Causal parents.** `Tracer.start` gives a child the parent's trace identifier and records the parent's span identifier. The tree structure is what the previous sections called causality, and the code never uses timestamps to establish it. `test_child_span_shares_trace_and_names_its_parent` checks the link.

**The outbox.** `write_outbox` stores the header in the row, and `relay` restores it and starts its span as a child of the original debit. The relay's start time minus the debit's end time is the delay the trace will show. `test_outbox_relay_stays_in_the_transfer_trace` uses a 300 ms delay so that the gap is visible. This is the propagation failure the overview warned about. Without the stored header, the credit becomes an orphan trace.

**Failure visibility.** `SpanScope.__exit__` records an exception as an `error` outcome and then returns `False`, so the exception continues to propagate. Instrumentation that swallows errors would hide the failures this section exists to show. `test_exception_is_recorded_and_not_swallowed` checks both halves.

**Bounded export.** `Exporter` drops the oldest span when full and counts the drop, so export never blocks the caller. This is the asynchronous-export trade-off from the trade-offs section. The drop counter is itself a metric, so a gap in traces is measurable. `test_exporter_counts_dropped_spans` checks the count.

**Tail sampling and routing.** `TailSampler.keep` sees the complete set of spans for a trace and keeps it if any span has a failure outcome or the trace exceeds the latency budget. The baseline draw uses the trace identifier, not a random number, so every collector agrees. `route` sends all spans for one trace to one collector, which is what makes a tail decision possible at all. `test_tail_sampler_keeps_failures_and_slow_traces` and `test_routing_is_stable_for_a_trace` check both rules. The sampler's `baseline_rate=0.0` in the test isolates the failure rules. In production the rate is small but not zero.

**Bounded labels and hashed references.** `Histogram.observe` rejects any label outside `ALLOWED_LABELS`, which is the cardinality rule from the core concepts section. It also caps the number of series and counts refused samples rather than blocking. `hashed_ref` replaces the account identifier with a keyed hash. The salt must be stored apart from the trace data, or the reference can be reversed by guessing. `test_histogram_rejects_account_label` and `test_hashed_reference_hides_the_account` check these.

**The protocol indicator.** `p99` computes the tail of the in-doubt age values. The test uses 100 values where only one is large, and the p99 is that outlier, which is the case the trade-offs section said a mean would hide.

**What the sketch does not model.** It has no network, so spans never arrive out of order or are lost in transit. It has no clock skew, so the causal structure is never tested against disagreeing clocks, which the clocks section will cover. Head sampling is absent, and the `sampled` flag is propagated but not used. Collectors are simulated by the `route` function alone, without buffering or timeouts. Each of these is a place where a production system needs more code and more tests.

## How to run it

Place `obs.py` and `test_obs.py` in one directory, and run `pytest -q`. The expected result is nine tests passing. If the outbox test fails, check that `write_outbox` stores the header and that `relay` calls `parse_traceparent` before starting its span. If the cardinality test fails, check that the label set has not been extended without review.

Key takeaway: The sketch shows that Kestrel's tracing is only as good as its propagation through the outbox, its causal parent links, its tail sampling on outcome with stable routing, its bounded metric labels, and its salted references, and the tests check each of these on the transfer and relay paths, though the code has not yet been compiled or run.

# Service Mesh Patterns: A Code Example

This example implements the mesh behaviors from the previous sections in one process: deadline propagation, route policy that separates safe retries from unsafe ones, a retry budget, outlier ejection with a maximum-ejection limit, idempotent shard operations, a status query for uncertain outcomes, and fail-static configuration. Time comes from an injected clock, and faults are injected per node and route. It is a teaching model. It has not been compiled or run, and the expected results below are design expectations until someone runs the tests.

## `mesh.py`

```python
"""Service mesh pattern sketch for Kestrel transfers.

Teaching model: one process, an injected clock, and in-memory shard nodes with
injected faults. It shows deadline propagation, route policy that separates safe
retries from unsafe ones, a retry budget, outlier ejection with a maximum-ejection
limit, idempotent shard operations, a status query for uncertain outcomes, and
fail-static configuration. It has not been compiled or run.
"""
from dataclasses import dataclass


class NotSent(Exception):
    """The connection failed before the request reached the node. Always safe to retry."""


class Timeout(Exception):
    """The request was sent and no response arrived. The outcome is unknown."""


class DeadlineExceeded(Exception):
    """The caller's budget is spent. No further attempts are made."""


@dataclass(frozen=True)
class RoutePolicy:
    idempotent: bool
    retry_on_timeout: bool
    timeout_ms: int

    def may_retry(self, error):
        if isinstance(error, NotSent):
            return True
        return isinstance(error, Timeout) and self.idempotent and self.retry_on_timeout


POLICY = {
    "balance.read": RoutePolicy(idempotent=True, retry_on_timeout=True, timeout_ms=150),
    "transfer.prepare": RoutePolicy(idempotent=True, retry_on_timeout=True, timeout_ms=200),
    "transfer.commit": RoutePolicy(idempotent=False, retry_on_timeout=False, timeout_ms=200),
    "transfer.status": RoutePolicy(idempotent=True, retry_on_timeout=True, timeout_ms=150),
}


class Clock:
    def __init__(self):
        self.now = 0.0

    def __call__(self):
        return self.now

    def tick(self, ms):
        self.now += ms


@dataclass(frozen=True)
class Deadline:
    at_ms: float

    def remaining(self, clock):
        return self.at_ms - clock()


class RetryBudget:
    """Caps retries at a fraction of requests, so a partial outage cannot multiply load."""

    def __init__(self, ratio=0.10, floor=3):
        self.ratio = ratio
        self.floor = floor
        self.requests = 0
        self.retries = 0

    def record_request(self):
        self.requests += 1

    def spend(self):
        allowance = max(self.floor, self.ratio * self.requests)
        if self.retries >= allowance:
            return False
        self.retries += 1
        return True


class ShardNode:
    """Idempotent by transaction id. Nodes of one shard share state, as if they share one log."""

    def __init__(self, name, store, effects):
        self.name = name
        self.store = store
        self.effects = effects

    def prepare(self, txid):
        if txid not in self.store:
            self.store[txid] = "prepared"
            self.effects.append(("prepare", txid))
        return self.store[txid]

    def commit(self, txid):
        state = self.store.get(txid)
        if state == "committed":
            return state
        if state != "prepared":
            raise ValueError(f"{self.name}: cannot commit {txid} from state {state}")
        self.store[txid] = "committed"
        self.effects.append(("commit", txid))
        return "committed"

    def status(self, txid):
        return self.store.get(txid, "unknown")


class Endpoint:
    def __init__(self, node):
        self.node = node
        self.calls = 0
        self.errors = 0
        self.ejected = False


class Shard:
    """Round-robin over nodes, with outlier ejection capped at max_eject_ratio of the nodes."""

    def __init__(self, name, n_nodes=2, max_eject_ratio=0.5, error_ratio=0.5, min_calls=5):
        store, effects = {}, []
        self.endpoints = [Endpoint(ShardNode(f"{name}-{i}", store, effects)) for i in range(n_nodes)]
        self.effects = effects
        self.max_eject = int(n_nodes * max_eject_ratio)
        self.error_ratio = error_ratio
        self.min_calls = min_calls
        self._next = 0

    def pick(self):
        live = [e for e in self.endpoints if not e.ejected] or self.endpoints
        endpoint = live[self._next % len(live)]
        self._next += 1
        return endpoint

    def record(self, endpoint, ok):
        endpoint.calls += 1
        if not ok:
            endpoint.errors += 1
        if endpoint.ejected or endpoint.calls < self.min_calls:
            return
        if endpoint.errors / endpoint.calls < self.error_ratio:
            return
        if sum(e.ejected for e in self.endpoints) < self.max_eject:
            endpoint.ejected = True


class Network:
    """Delivers one call to one node. Faults are injected per node and route."""

    def __init__(self, clock, latency_ms=20):
        self.clock = clock
        self.latency_ms = latency_ms
        self.faults = {}

    def inject(self, node_name, route, *faults):
        self.faults.setdefault((node_name, route), []).extend(faults)

    def deliver(self, node, route, action, deadline):
        remaining = deadline.remaining(self.clock)
        if remaining <= 0:
            raise DeadlineExceeded(route)
        queue = self.faults.get((node.name, route), [])
        fault = queue.pop(0) if queue else None
        if fault == "not_sent":
            raise NotSent(node.name)
        result = action(node)  # the node may apply the effect here
        self.clock.tick(self.latency_ms)
        limit = min(POLICY[route].timeout_ms, remaining)
        if fault == "lost" or self.latency_ms > limit:
            raise Timeout(f"{node.name} {route}")
        return result


class Mesh:
    """Client side: applies route policy, the retry budget, and outlier tracking."""

    def __init__(self, network, budget=None):
        self.network = network
        self.budget = budget or RetryBudget()
        self.retries_made = 0

    def call(self, route, shard, action, deadline):
        self.budget.record_request()
        while True:
            endpoint = shard.pick()
            try:
                result = self.network.deliver(endpoint.node, route, action, deadline)
            except (NotSent, Timeout) as error:
                shard.record(endpoint, ok=False)
                if not POLICY[route].may_retry(error) or not self.budget.spend():
                    raise
                self.retries_made += 1
                continue
            shard.record(endpoint, ok=True)
            return result


class Transfer:
    """Coordinator for one transfer across two shards. Every call goes through the mesh."""

    def __init__(self, mesh, decision_log):
        self.mesh = mesh
        self.decision_log = decision_log

    def run(self, txid, source, target, deadline):
        self.mesh.call("transfer.prepare", source, lambda n: n.prepare(txid), deadline)
        self.mesh.call("transfer.prepare", target, lambda n: n.prepare(txid), deadline)
        self.decision_log[txid] = "commit"  # durable before any commit is sent
        try:
            self.mesh.call("transfer.commit", source, lambda n: n.commit(txid), deadline)
            self.mesh.call("transfer.commit", target, lambda n: n.commit(txid), deadline)
        except Timeout:
            return self._resolve(txid, source, target, deadline)
        return "committed"

    def _resolve(self, txid, source, target, deadline):
        # A timed-out commit is not an abort. The decision is logged, so ask the shards.
        if self.decision_log.get(txid) != "commit":
            raise RuntimeError(f"{txid}: no commit decision logged")
        for shard in (source, target):
            state = self.mesh.call("transfer.status", shard, lambda n: n.status(txid), deadline)
            if state == "committed":
                continue
            if state == "prepared":
                # Application-level re-send, not a mesh retry. Commit is idempotent by txid.
                self.mesh.call("transfer.commit", shard, lambda n: n.commit(txid), deadline)
            else:
                raise RuntimeError(f"{txid} unresolved on {shard}: {state}")
        return "committed"


class ConfigCache:
    """Fail-static: keeps the last configuration received when the control plane is unreachable."""

    def __init__(self, routes):
        self.version = 0
        self.routes = routes

    def sync(self, fetch):
        try:
            version, routes = fetch()
        except ConnectionError:
            return self.version
        if version > self.version:
            self.version, self.routes = version, routes
        return self.version
```

