    compare, credit_fee, deposit, execute, load_account, make_event,
    read_at_least, rebuild, transfer,
)


def seeded_store():
    store = EventStore()
    deposit(store, "acct:X", "dep-1", 100000)  # 1,000.00
    deposit(store, "acct:Y", "dep-2", 4000)    # 40.00
    return store


def test_concurrent_append_is_rejected():
    store = EventStore()
    first = make_event("acct:X", "FundsDeposited", {"txid": "a", "amount": 1})
    second = make_event("acct:X", "FundsDeposited", {"txid": "b", "amount": 2})
    store.append("acct:X", 0, [first])
    with pytest.raises(ConcurrencyError):
        store.append("acct:X", 0, [second])


def test_retried_append_is_a_noop():
